namespace SeedRegistryLab;

// Frozen original behavior for reproduction; do not edit this file.
public sealed class BaselineRegistry
{
    private readonly HashSet<SeedAccession> _items = new();
    public int Count => _items.Count;

    public bool Register(string code) => _items.Add(new SeedAccession(code));

    public bool CorrectCode(string oldCode, string newCode)
    {
        var item = _items.FirstOrDefault(x => x.Code == oldCode);
        if (item is null) return false;
        if (_items.Any(x => x.Code == newCode && !ReferenceEquals(x, item))) return false;
        item.Code = newCode;
        return true;
    }

    public bool ContainsCode(string code) => _items.Contains(new SeedAccession(code));
    public bool RemoveCode(string code) => _items.Remove(new SeedAccession(code));
}
